2: import { afterEach, beforeEach, describe, expect, it } from 'vitest';
3: import { createBattleEngine } from '@empire/battle-engine';
4: import { CANDIDATE_01_CONTENT_PACK, CANDIDATE_01_LEVELS } from '@empire/story-candidate-01';
