15: /** Headless adapter/timing evidence, not browser texture or live combat acceptance. */
16: describe('Gray Flag registered hit phase playback', () => {
17:   it('plays the approved slash once at 12 fps, holds its fade, and removes it at 420 ms', async () => {
18:     const content = createTestCatalog(CANDIDATE_01_CONTENT_PACK);
19:     const engine = createBattleEngine({ content });
20:     const state = engine.createState(CANDIDATE_01_LEVELS[0]);
21:     const before = JSON.stringify(state);
22:     const board = new BoardView({ content, grid: engine.rules.grids.get('square4'),
23:       art: CANDIDATE_01_ART, renderer: svgBoardSurface }, state, {
24:       onTileClick: () => {}, onTileEnter: () => {}, onLeave: () => {},
25:       onSecondary: () => {}, onScale: () => {},
26:     });
27:     try {
28:       const at = { x: state.units[0].x, y: state.units[0].y };
29:       const played = board.animateHit(at, 12, false, 'c01.border-blade');
30:       const effect = board.el.querySelector('.fx')!;
31:       const strip = effect.querySelector('svg')!;
32:       expect(effect.getAttribute('transform')).toBe(`translate(${(at.x * 32 + 16).toFixed(2)},${(at.y * 32 + 16).toFixed(2)})`);
33:       expect(strip.querySelector('image')!.getAttribute('href')).toContain('/runtime-hd/fx/fx-01.png');
34:       expect(strip.getAttribute('x')).toBe('-16');
35:       expect(strip.getAttribute('y')).toBe('-16');
36:       expect(effect.querySelectorAll('[data-part="burst"] circle')).toHaveLength(1);
37:       expect(effect.querySelector('[data-part="number"]')!.textContent).toBe('-12');
38:       for (const [ms, frame] of [[0, 0], [83.34, 1], [166.67, 2], [250, 3], [419, 3]]) {
39:         clock.at(ms);
40:         await Promise.resolve();
41:         expect(strip.getAttribute('viewBox')).toBe(`${frame * 32} 0 32 32`);
42:         expect(board.el.contains(effect)).toBe(true);
43:       }
44:       clock.at(420);
45:       await played;
46:       expect(board.el.querySelector('.fx')).toBeNull();
47:       expect(JSON.stringify(state)).toBe(before);
48:     } finally {
49:       board.dispose();
50:     }
51:   });
52: });
